import{_ as i,a as e,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"操作系统复习题与易错点 · 知识摘录速查","description":"区分历史课程知识摘录与自测题，按进程调度、内存、文件和 I/O 展开参考解答。","frontmatter":{"title":"操作系统复习题与易错点 · 知识摘录速查","description":"区分历史课程知识摘录与自测题，按进程调度、内存、文件和 I/O 展开参考解答。","splitFrom":"principles/fundamentals/operatingsystemserror.md","showdocs":{"topics":[{"id":"fundamentals","title":"操作系统原理","link":"/topics/fundamentals/"}],"kind":"调度与并发推演","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"操作系统复习题与易错点","summary":"区分历史课程知识摘录与自测题，按进程调度、内存、文件和 I/O 展开参考解答。","status":"active","related":[{"title":"操作系统（02323）：概念与资源管理笔记","link":"/principles/fundamentals/operatingsystems","kind":"持久性与参考","scope":"general","audience":"general"},{"title":"操作系统（02323）：概念与资源管理笔记 · 操作系统概论至概念与资源","link":"/principles/fundamentals/operatingsystems-part-01","kind":"持久性与参考","scope":"general","audience":"general"},{"title":"操作系统（02323）：概念与资源管理笔记 · 进程与调度至I/O 设备管理","link":"/principles/fundamentals/operatingsystems-part-02","kind":"持久性与参考","scope":"general","audience":"general"},{"title":"进程、内存与持久性的工作方式","link":"/principles/fundamentals/operating-system-mechanisms","kind":"资源与计算机制","scope":"general","audience":"general"},{"title":"语言与运行时官方文档入口","link":"/principles/fundamentals/official-documentation","kind":"资源与计算机制","scope":"general","audience":"general"}],"prev":{"text":"操作系统复习题与易错点 · 操作系统概论复习至知识摘录速查","link":"/principles/fundamentals/operatingsystemserror-part-01"},"next":{"text":"操作系统复习题与易错点 · 填空答案速查至按主题自测","link":"/principles/fundamentals/operatingsystemserror-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"操作系统复习题与易错点 · 操作系统概论复习至知识摘录速查","link":"/principles/fundamentals/operatingsystemserror-part-01"},"next":{"text":"操作系统复习题与易错点 · 填空答案速查至按主题自测","link":"/principles/fundamentals/operatingsystemserror-part-03"}},"headers":[],"relativePath":"principles/fundamentals/operatingsystemserror-part-02.md","filePath":"principles/fundamentals/operatingsystemserror-part-02.md"}'),n={name:"principles/fundamentals/operatingsystemserror-part-02.md"};function r(p,l,s,a,u,c){return e(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="操作系统复习题与易错点-·-知识摘录速查" tabindex="-1">操作系统复习题与易错点 · 知识摘录速查 <a class="header-anchor" href="#操作系统复习题与易错点-·-知识摘录速查" aria-label="Permalink to &quot;操作系统复习题与易错点 · 知识摘录速查&quot;">​</a></h1><p><a href="/principles/fundamentals/operatingsystemserror">返回分篇目录</a></p><ul><li><p>文件的类型</p><ul><li>正规文件：包含用户信息一般分为 ASCII 文件和二进制文件</li><li>目录文件：管理文件的系统文件</li><li><strong>字符设备文件</strong>：和输入/输出有关用于串行 IO 类设备，如终端、打印机和网络等</li><li>块设备文件：磁盘类设备</li></ul></li><li><p>死锁</p><ul><li>处理死锁的基本方法有 <ul><li>预防死锁</li><li>避免死锁</li><li>检测并解除死锁</li><li>忽略死锁（接受风险，不等于证明死锁不可能发生）</li></ul></li></ul></li><li><p>Linux 的伙伴系统</p><blockquote><p>历史教材按 0 至 10 阶列出 1、2、4、…、1024 页的空闲块，这是示例参数，不是所有 Linux 版本的固定上限。若页大小为 4 KiB，1024 页对应 4 MiB；实际页大小与可分配阶数须按目标内核和架构核对。参见 <a href="https://www.kernel.org/doc/gorman/html/understand/understand009.html" target="_blank" rel="noopener noreferrer">Linux 物理页分配的阶数说明</a>与<a href="https://docs.kernel.org/admin-guide/mm/concepts.html" target="_blank" rel="noopener noreferrer">页大小的架构边界</a>。</p></blockquote></li><li><p>自调度算法（历史摘录待核对）</p><p>原稿未注明具体算法或课程页码，以下特点不能直接对应某个 Linux 调度器；需课程资料拥有者确认“自调度”的原意。</p><ul><li>最常用的调度方式之一</li><li>最简单的一种调度方式</li><li>优点 <ul><li>易移植</li><li>有利于提高 CPU 的利用率</li></ul></li></ul></li><li><p>存储器的种类(<code>CPU</code> 寄存器保存最常用的数据)</p><ul><li>靠近 CPU 的容量小、速度快的高速缓存存储器作为速度相对较慢、容量较大的主存中数据和指令子集的缓冲区。</li><li>主存暂时存放存储容量更大、速度更慢的磁盘上的数据</li><li>而这些磁盘常常又作为存储在通过网络连接的其他机器的磁盘或磁带上的数据的缓冲区</li></ul></li><li><p>程序的链接</p><blockquote><p>链接程序<strong>不属于操作系统</strong>的构成部分，但是它为操作系统提供可装入的程序模块</p></blockquote><ul><li>可以把链接分为静态链接和动态链接 <ul><li><strong>静态</strong>链接： <ul><li><strong>在程序运行前</strong>，用链接程序将目标模块链接成一个完整的装入模块</li><li>静态链接程序的任务一是对逻辑地址进行修改，二是变换外部调用符号</li></ul></li><li>动态链接</li></ul></li></ul></li><li><p>连续分配的类型</p><blockquote><p>连续分配是指操作系统分配内存时，为每个进程分配一块物理地址连续的内存空间</p></blockquote><ul><li>单一连续区分配方式</li><li>固定分区分配方式</li><li>动态分区分配方式</li></ul></li><li><p>内存分配主要任务是<strong>为每道程序分配内存空间</strong></p></li><li><p>动态分区分配算法</p><ul><li>首次适应算法</li><li><strong>循环首次适应算法</strong><ul><li>优点：空闲区分布均勾、查找开销较小</li><li>缺点：容易使系统缺之大空闲区</li></ul></li><li>最佳适应算法</li></ul></li><li><p>分页管理</p><blockquote><p>页表是系统为进程建立的数据结构，页表的作用是实现从页号到页框号的映射</p></blockquote><ul><li>页：将一个进程的逻辑地址空间分成若干个大小相等的片</li><li>页框或页顿：将物理内存空间分成与页大小相同的若干个存储</li><li>页内碎片：进程的最后一页一般装不满一个页框，而形成了不可利用的碎片</li></ul></li><li><p>分页和分段的区别</p><blockquote><p>分页和分段都属于离散分配方式，都要通过数据结构与硬件的配合来实现逻辑地址到物理地址的映射，但两者存在着很大的不同</p></blockquote><ul><li>页是按物理单位划分的，<strong>分页的引入</strong>是为了提高内存的<strong>利用率</strong>和支持虚拟存储。而段是按逻辑单位划分的，一个段含有一组意义相对完整的信息。引入分段的目的是为了方便程序员编程</li><li>页的大小是固定的。而段的大小不固定，取决于用户编写的程序和编译器</li><li><strong>分页</strong>的地址空间是<strong>一维</strong>的，程序员给出的地址只是一个助记符，已知的逻辑地址是一个数,如 2568。<strong>分段</strong>的地址空间是<strong>二维</strong>的，程序员在标识一个逻辑地址时需要给出两个数：一个是段号，一个是段内偏移</li></ul></li><li><p><strong>虚拟存储技术</strong></p><ul><li><p>系统的特征</p><ol><li>离散性</li><li>多次性</li><li>对换性</li><li>虚拟性</li></ol></li><li><p>好处</p><ul><li>提高内存利用率</li><li>提高多道程序度</li><li>把逻辑地址空间和物理地址空间分开，使程序员不用关心物理内存的容量对编程的限制</li></ul></li></ul></li><li><p>文件结构</p><ul><li><p>分类</p><ul><li>树形结构</li><li>无结构字节序列</li><li>固定长度记录序列</li></ul></li><li><p>无结构字节序列（流式文件）</p><ul><li>操作系统不知道也不关心文件内容是什么，操作系统所见到的就是<strong>字节</strong>，其任何含义由使用该文件的程序自行理解</li><li>在 UNIX 和 Windows 系统中都采用这种方式</li></ul></li></ul></li><li><p>目录结构</p><ul><li>文件目录的组织和管理是文件管理的一个重要方面，包括单层目录、两级和树形目录</li><li>树形目录 <ul><li>优点：便于文件的分类，层次结构清晰，便于管理和保护，解决了重名问题，查找速度加快</li><li>缺点：查找一个文件按路径名逐层检查，由于每个文件都放在外存中，多次访问磁盘会影响速度，<strong>结构相对复杂</strong></li></ul></li><li>每个目录项包含对应文件<strong>文件名</strong> 和 <strong>i 结点号</strong></li></ul></li><li><p>FAT 文件系统</p><ul><li>FAT 文件系统有 3 个版本：FAT-12.FAT-16 和 FAT-32，取决于用多少个二进制位存放号</li></ul></li><li><p>DMA 控制方式</p><ul><li>命令/状态寄存器（CR）用于接收从 CPU 发来的 VO 命令或有关控制信息、设备状态</li><li>内存地址寄存器（MAR）用于存放内存地址</li><li>数据计数器（DC）用于指示 DMA，本次向 CPU 发中断信号前要读或写数据的次数</li><li>数据寄存器（DR）用于暂存 DMA 传输中要输入或输出的数据</li></ul></li><li><p>缓冲池</p><ul><li>公共缓冲池既可用于输入，又可用于输出</li><li>其中至少包含 3 种类型的缓冲区、3 种缓冲队列和 4 种工作缓冲区</li></ul></li><li><p>进程切换的步骤</p><blockquote><p>进程切换使当前正在执行的进程成为被替换进程，出让其所使用的 CPU，以运行被进程调度程序选中的新进程</p></blockquote><ol><li>保存包括程序计数器和其他寄存器在内的 CPU 上下文环境</li><li>更新被替换进程的进程控制块</li><li>修改进程状态，把执行态改为就绪态或者阻塞态</li><li>将被替换进程的进程控制块移到就绪队列或阻塞队列</li><li>执行通过进程调度程序选择的新进程，并更新该进程的进程控制块</li><li>更新内存管理的数据结构</li><li>恢复被调度程序选中的进程的硬件上下文</li></ol></li><li><p>进程控制块（PCB）：组织方式通常<strong>链接</strong>和<strong>索引</strong>两种</p></li><li><p>实时计算的概念</p><blockquote><p>实时系统是支持实时计算的系统。实时计算的正确性不仅依赖于系统计算的逻辑结果，还依赖于产生正确结果的时间</p></blockquote></li><li><p>实时系统的特点（在实时系统中，往往采取多级容错措施来保证系统安全和数据安全）</p><ul><li>实时系统主要用于实时控制和实时信息处理领域</li><li>实时系统比分时系统要求有更高的可靠性</li><li>因为任何实时系统的错误都可能带来巨大的经济损失，甚至危及生命安全</li></ul></li><li><p>操作系统中的用户接口（批处理用户接口）</p><blockquote><p>脱机用户接口是为批处理作业的用户提供的</p></blockquote></li><li><p>操作系统体系结构</p><ul><li>简单的监控程序模型的经典代表是（<code>FMS</code> &amp; <code>IBSYS</code>）</li><li>动态可扩展结构模型的典型代表是 Harvard 大学的 VINO 操作系统</li><li>分层结构最经典的例子是 Dijkstra 的 THE 系统</li><li>客户/服务器模型的典型代表是卡内基梅隆大学研制的 Mach 操作系统、WindRiver 公司的 Vxworks 等</li></ul></li><li><p>操作系统中最核心概念（<strong>进程</strong>），也是围绕进程展开的</p></li><li><p>进程控制块中的处理机状态信息</p><ul><li>通用寄存器</li><li>指令计数器</li><li>程序状态字 PSW</li><li>用户栈指针。其中，指令<strong>计数器</strong>中存放了 <code>CPU</code> 要访问的<strong>下一条指令</strong>的地址</li></ul></li><li><p>进程状态的转换</p><blockquote><p>进程状态不能由阻塞态直接变为执行态，进程状态由阻塞态变为就绪态的过程称为唤醒过程由执行态变为阻塞态的过程称为阻塞过程</p></blockquote><ul><li>执行态 <ul><li>-<code>时间片用完</code>-&gt;就绪态</li><li>-<code>等待事件</code>-&gt;阻塞态</li></ul></li><li>就绪态-<code>进程调度</code>-&gt;执行态</li><li>阻塞态-<code>等待的事件发生</code>-&gt;就绪态</li></ul></li><li><p>程序顺序执行时具特点有：</p><ul><li>顺序性</li><li>封闭性</li><li>可再现性</li></ul></li><li><p>系统调用的类型</p><ul><li>进程控制类系统调用：创建、撤销进程；获得、改变进程属性</li><li>文件操纵类系统调用：创建文件、删除文件、打开文件、关闭文件和读/写文件</li><li>设备管理类系统调用：请求、释放设备</li><li>通信类系统调用：打开、关闭连接，交换信息</li><li>信息维护类系统调用：返回系统当前日期、时间、版本号、用户数、空闲内存和磁盘空间大小等信息</li></ul></li><li><p>操作系统内核的功能</p><ul><li>中断处理、时钟管理和原语操作</li><li>操作系统内核的资源管理功能包括进程管理、存储器管理和设备管理</li></ul></li><li><p>操作系统中的时钟</p><ul><li>别称为实时时钟（RTC） <blockquote><p>也称 CMOS 时钟，是一块时钟芯片，靠电池供电，为计算机提供计时标准，是最原始、最底层的数据</p></blockquote></li><li>OS 时钟 <blockquote><p>OS 时钟产生于 PC 主板上的定时/计数芯片，在开机时有效，由操作系统控制</p></blockquote></li></ul></li><li><p>进程调度的功能</p><blockquote><p>进程调度功能由操作系统内核的进程调度程序完成，在 Linux 内核中，进程调度功能的实现从调用内核函数 schedule()开始。进程调度的功能是按照某种策略和算法从就绪态进程（在 Linux 中是可执行进程）中为当前空闲的 CPU 选择在其上运行的新进程</p></blockquote></li><li><p>选择调度方式和算法的准则</p><ol><li>周转时间短</li><li>响应时间快</li><li>截止时间的保证</li><li>系统吞吐量高</li><li>处理机利用率好</li></ol></li><li><p>操作系统负责管理计算机的<strong>资源</strong></p></li><li><p>other</p><ul><li>若有效执行时间片为 200、每次切换耗时为 10，则切换时间/执行时间为 5%；切换占总耗时的比例为 10/(200+10)≈4.76%，须先明确分母。</li></ul></li></ul>',3)])])}const m=i(n,[["render",r]]);export{d as __pageData,m as default};
